from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
MANAGER = (ROOT / 'app/src/main/java/vn/kholinhkien/BackupManager.kt').read_text()
INSPECTOR = (ROOT / 'app/src/main/java/vn/kholinhkien/BackupArchiveInspector.kt').read_text()
PARSER = (ROOT / 'app/src/main/java/vn/kholinhkien/ZipCentralDirectoryVerifier.kt').read_text()
checks = []
def check(name, condition): checks.append((name, bool(condition)))
check('MediaStore read-back payload verification precedes central-directory verification', MANAGER.index('BackupArchiveInspector.verify(readBack, ownerId)') < MANAGER.index('ZipCentralDirectoryVerifier.verify(channel)'))
check('MediaStore row is published only after both verification passes', MANAGER.index('ZipCentralDirectoryVerifier.verify(channel)') < MANAGER.index('put(MediaStore.MediaColumns.IS_PENDING, 0)'))
check('MediaStore central-directory check uses seekable file descriptor', 'resolver.openFileDescriptor(uri, "r")' in MANAGER and 'FileInputStream(pfd.fileDescriptor).channel' in MANAGER)
check('Android 8/9 partial file central-directory check precedes rename', MANAGER.index('ZipCentralDirectoryVerifier.verify(archive.channel)') < MANAGER.index('partial.renameTo(target)'))
check('Central-directory entry names must exactly match read-back entries', 'centralEntries == verifiedEntries' in MANAGER)
check('ZIP size is bounded and EOCD is searched from legal tail window', 'MAX_ARCHIVE_BYTES' in PARSER and '22L + 65535L' in PARSER)
check('EOCD rejects multi-disk, ZIP64 sentinels, comments and trailing data', 'diskNumber == 0 && centralDisk == 0' in PARSER and 'entryCount != 0xffff' in PARSER and 'commentLength == 0 && centralOffset + centralSize == eocdOffset' in PARSER)
check('Central directory count, signatures and exact byte length are checked', 'entryCount in 1..MAX_ENTRIES' in PARSER and 'u32(header, 0) == CENTRAL' in PARSER and 'cursor == centralOffset + centralSize' in PARSER)
check('Encryption, unsupported flags, methods and ZIP64 fields are rejected', 'flags and UTF8_FLAG != 0' in PARSER and 'method == 8' in PARSER and 'extraLength == 0' in PARSER and 'externalAttributes == 0L' in PARSER)
check('UTF-8 names are strictly decoded and constrained to app payload paths', 'CodingErrorAction.REPORT' in PARSER and 'isSafeName(name)' in PARSER)
check('Local headers must match central names, flags and compression method', 'u32(local, 0) == LOCAL' in PARSER and 'localFlags == flags && localMethod == method' in PARSER and 'localName == name' in PARSER)
check('Data descriptors are checked against central CRC and sizes', 'u32(descriptor, 0) == DESCRIPTOR' in PARSER and 'u32(descriptor, 4) == crc' in PARSER)
check('Local entry ranges cannot overlap or extend into central directory', 'dataEnd <= centralOffset' in PARSER and 'ordered[index - 1].last + 1L == ordered[index].first' in PARSER and 'ordered.first().first == 0L' in PARSER and 'ordered.last().last + 1L == centralOffset' in PARSER)
check('Parser uses bounded positional reads and detects truncated archives', 'channel.read(buffer, offset)' in PARSER and 'ZIP bị cắt cụt' in PARSER)
check('Read-back verifier returns verified entry-name set for structural cross-check', 'fun verify(input: InputStream, expectedOwnerId: String): Set<String>' in INSPECTOR and 'return seen' in INSPECTOR)
for name, ok in checks: print(('PASS' if ok else 'FAIL') + ' ' + name)
print(f'{sum(ok for _, ok in checks)}/{len(checks)} PASS')
if not all(ok for _, ok in checks): raise SystemExit(1)
